import {isElapsedWorldWar} from './world-war.js';
import {commanderReport} from './commander-report.js';
import {worldWarScenario} from './world-war.js';
import {settledOwners,UNITED_LEAGUE} from './league-settlement.js';
import {adventureTimeLabel} from '../../experiments/day-night/opening-time-label.js';
import {roadsideReport} from './roadside-report.js';

// Read-only projection of the actual event log, regenerated by Save/Continue.
// No re-simulation, time travel, scenery loading, or second campaign is started.
export function campaignChronicle(state,clock=null){
  if(!state)return null;
  const elapsed=isElapsedWorldWar(state.scenario);
  const at=event=>elapsed?(event.elapsedSeconds??event.day*60):event.day;
  const present=elapsed?(clock?.elapsedSeconds??Math.max(0,...state.events.map(at))):state.day;
  const scenario=worldWarScenario(state.scenario),name=id=>scenario.regions.find(r=>r.id===id)?.name??id;
  const side=id=>scenario.factions.find(f=>f.id===id)?.short??id;
  let owners=Object.fromEntries(scenario.regions.map(r=>[r.id,r.owner])),winner=null;
  const groups=new Map(),frames=[];
  for(const e of state.events){if(e.day>state.day||at(e)>present)continue;const key=at(e);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e);}
  frames.push({day:0,...(elapsed?{elapsedSeconds:0}:{}),title:'Your campaign begins',caption:'Teresod arrives in neutral Minora. West Lizeem holds Nethereum and Ovesos; East Lizeem holds Caricas and Nesdor. These are the events of your saved campaign.',owners:{...owners},seconds:3,war:true,highlight:[],routes:[],battles:[]});
  const active=new Map();
  for(const [time,events]of groups){
    const day=events[0].day;
    const lines=[],routes=[],highlight=new Set();let title='The armies move',priority=0;
    const head=(text,p)=>{if(p>=priority){title=text;priority=p;}};
    for(const e of events){
      if(['march','retreat'].includes(e.type)){
        const a=e.army;routes.push({from:a.from,to:a.to,owner:a.owner,retreat:e.type==='retreat',armyId:a.id});
        lines.push(`${side(a.owner)} ${e.type==='retreat'?'retreats':'marches'} from ${name(a.from)} to ${name(a.to)} (arrival ${elapsed?adventureTimeLabel(a.arrives*60):'day '+a.arrives}).`);
      }else if(e.type==='battle-start'){
        const b=e.engagement;active.set(b.id,{id:b.id,region:b.region,owner:b.attacker});highlight.add(b.region);head(`Battle at ${name(b.region)}`,2);
        lines.push(`${side(b.attacker)} attacks ${side(b.defender)} in ${name(b.region)}.`);
      }else if(e.type==='roadside-result'){
        const report=roadsideReport(e,{region:name,faction:side,elapsed});
        head(report.title,3);highlight.add(e.region);lines.push(report.detail);
        if(e.alliesLost)lines.push(`${e.alliesLost} allied scout${e.alliesLost===1?' was':'s were'} lost${e.support?' from '+e.support.name:''}.`);
      }else if(e.type==='hero-result'){
        head(`Your intervention at ${name(e.region)}`,3);highlight.add(e.region);
        if(e.reason==='declined'||!e.faction){lines.push(`You stayed out of the battle at ${name(e.region)}.`);continue;}
        if(e.objective?.type==='duel'){lines.push(`You challenged the opposing champion for ${side(e.faction)} at ${name(e.region)}: ${e.outcome==='success'?'the champion yielded; two rally guards fell back':e.outcome==='withdraw'?'you yielded':'the challenge was lost'}. No enemy soldiers died in the duel. The final assault remained to be fought.`);continue;}
        lines.push(`You fought for ${side(e.faction)} at ${name(e.region)}: ${e.outcome==='success'?(e.objective?'interception won':'skirmish won'):e.outcome==='withdraw'?'withdrew':'defeated'}${e.objective?`; ${e.objective.removed??e.objective.blocked??0} reinforcement strength removed`:''}.`);
      }else if(e.type==='rally-result'){
        head(`Your final assault at ${name(e.region)}`,3);highlight.add(e.region);
        lines.push(`Your assault for ${side(e.faction)} ${e.outcome==='success'?'broke the enemy line':e.outcome==='withdraw'?'withdrew':'was repelled'}; ${e.removed??0} enemy strength removed.${e.progress?.alliesLost!==undefined?` ${e.progress.alliesLost} allies lost; ${e.progress.routed} enemies routed, not killed.`:''}`);
      }else if(e.type==='battle'){
        if(e.commanders)lines.push(commanderReport(e));
        const victor=e.captured?e.attacker:e.defender;if(e.captured)owners[e.region]=victor;
        active.delete(e.engagementId);highlight.add(e.region);head(`${side(victor)} ${e.captured?'takes':'holds'} ${name(e.region)}`,4);
        lines.push(`${side(victor)} ${e.captured?'captured':'held'} ${name(e.region)}. Battle losses: ${side(e.attacker)} ${e.attackLoss}, ${side(e.defender)} ${e.defenseLoss}.${e.resolution==='rally-rout'?' Your final assault decided this field.':''}`);
      }else if(e.type==='intervention'){
        lines.push(`A testing intervention added ${e.amount} strength to ${side(e.faction)} in ${name(e.region)}.`);
      }else if(e.type==='victory'){
        winner=e.faction;head('The Lizeemi League',5);
        lines.push(`${side(winner)} won the war. The united country is the ${UNITED_LEAGUE}, retaining the victor's colors. Minora is its seat; ${winner==='west'?'the Mayor':'the High Priest'} leads the Council of Three.`);
      }
    }
    if(!lines.length)continue;
    frames.push({day,...(elapsed?{elapsedSeconds:time}:{}),title,caption:lines.join('\n\n'),seconds:Math.min(6,2+lines.length),owners:settledOwners(owners,winner),winner,highlight:[...highlight],routes,battles:[...active.values()].map(b=>({...b})),war:!winner});
  }
  if(frames.at(-1).day!==state.day||!winner)frames.push({day:state.day,...(elapsed?{elapsedSeconds:present}:{}),title:winner?'The war is settled':'Your campaign so far',caption:winner?'The memory has reached your present.':`You have reached ${elapsed?adventureTimeLabel(present):'day '+state.day}. ${active.size?`${active.size} battle${active.size===1?' is':'s are'} still underway.`:'The war continues.'} ${elapsed&&clock?.complete&&!clock.fullCampaign?'This opening experiment is complete; the wider war is unresolved.':'The next events have not happened yet.'}`,seconds:3,owners:settledOwners(owners,winner),winner,war:!winner,routes:[],battles:[...active.values()],highlight:[]});
  return {id:`campaign:${state.scenario}:${state.seed}:${elapsed?present:state.day}`,kind:'campaign',...(elapsed?{timeline:'elapsed',elapsedSeconds:present}:{}),deviceName:'Chronoscope / Your campaign',dayLabel:elapsed?'ADVENTURE':'CAMPAIGN DAY',lastDay:state.day,frames,factions:scenario.factions.map(f=>({...f})),regions:scenario.regions.map(r=>({id:r.id,position:{...r.position}}))};
}
